import pandas as pd

def clean(df):
    df = df.copy()
    df['flipper_length_mm'] = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]
    return df

def answer(df):
    result = {}
    for species, group in df.groupby('species'):
        if pd.isna(species):
            continue
        result[species] = group['flipper_length_mm'].mean()
    return result
